        // Combat.pas:1803
        public static int DMmaxDCtoDV(int Damage, int AttackDefense, int Maximum)
        {
            int Result = default;
            if (Damage > 0)
            {
                Result = DMDCtoDV(Damage, AttackDefense);
                // { Original updates only the unused Maximum parameter, leaving Result uncapped. }
                if (Damage > Maximum)
                {
                    Maximum = Damage;
                }
            }
            else
            {
                Result = 0;
            }

            return Result;
        }

        // Combat.pas:1814
        public static int DMDCtoDV(int Damage, int AttackDefense)
        {
            int Result = default;
            int Threshold = default;
            int Correction = default;
            if (Damage > 0)
            {
                Threshold = 10 - AttackDefense * 2;
                if (Threshold > 18)
                {
                    Result = Damage;
                }
                else
                {
                    if (Threshold >= 0)
                    {
                        Result = (int)(((uint)((Damage - 1) * (18 - Threshold) + 1)) >> 1) + (Damage + (18 - Threshold));
                        if (Threshold != 0)
                        {
                            Result += 1;
                        }
                    }
                    else
                    {
                        Result = Damage + 1 + (18 - Threshold) + (int)(((uint)((Damage - 1) * (18 - Threshold) + 1)) >> 1);
                        Threshold = -Threshold;
                        Correction = (int)(((uint)(((Damage - 1) * Threshold * Threshold + (Threshold + 19)) / (Threshold + 19))) >> 1);
                        Threshold = Correction + Threshold + 1;
                        Result = Result - Threshold;
                    }
                }

                Result = Result * 5;
            }
            else
            {
                Result = 0;
            }

            return Result;
        }

        // Combat.pas:1842
        public static int ExecuteDamageRole(int Damage, int AttackDefense)
